import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();

        int n = s.length();
        int insertions = 0;
        int i = 0;

        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) {
                j++;
            }
            int runLength = j - i;
            if (runLength % 2 == 0) {
                insertions++;
            }
            i = j;
        }

        System.out.println(insertions);
    }
}
